<template>
  <div class="scene-editor">
    <header class="editor-header"><strong>Tomori Studio <em>v2</em></strong><span>场景 · {{ project.clips.length }} 个模型片段</span><div class="header-actions"><button :aria-pressed="previewExpanded" @click="previewExpanded=!previewExpanded">{{previewExpanded ? '返回编辑' : '放大画布'}}</button><button v-if="!previewExpanded" :aria-pressed="showAssets" @click="showAssets=!showAssets">素材库</button><button v-if="!previewExpanded" :aria-pressed="showInspector" @click="showInspector=!showInspector">片段属性</button><ShortcutManual /><button :disabled="!canUndo" title="撤销 Ctrl+Z" @click="undo">撤销</button><button :disabled="!canRedo" title="重做 Ctrl+Shift+Z / Ctrl+Y" @click="redo">重做</button><button @click="exportProject">导出工程</button><button :disabled="locked" @click="projectInput.click()">导入工程</button><button @click="emit('legacy')" :disabled="locked">打开 v1 编辑器</button><input ref="projectInput" type="file" accept=".json" hidden @change="importProject" /></div></header>
    <div v-if="message" class="editor-message" role="status">{{ message }}<button @click="message=''">关闭</button></div>
    <div class="editor-workspace">
      <aside v-show="!previewExpanded && showAssets" class="asset-panel"><h3>模型素材库</h3><input v-model="assetSearch" placeholder="搜索模型素材" /><p>点击添加片段，可重复使用同一模型</p><button v-for="model in filteredModels" :key="model.category+'/'+model.name" class="asset-item" :disabled="locked" @click="addModel(model)"><b>{{ model.category }}</b><span>{{ model.name }}</span><i>＋</i></button></aside>
      <main class="scene-main"><SceneCanvas ref="sceneCanvas" :clips="project.clips" :time="time" :fps="project.fps" :selected="selected" :runtimes="runtimes" :playing="playing" :background="project.background" :background-image="project.backgroundImage" @background-ready="backgroundLoading=false" :recording="recorder.isRecording.value" @ready="runtimeReady" @dispose="disposeRuntime" @error="runtimeError" @select="selectedId=$event" @move="moveModel" @transform="transformModel" @mouse-position="mouseMoved" @begin-edit="beginEdit" @end-edit="endEdit" />
        <div class="transport"><button @click="seek(0)" :disabled="recorder.isRecording.value">回到开头</button><button @click="playing ? pause() : play()" :disabled="loading || recorder.isRecording.value">{{ playing ? '暂停' : '播放' }}</button><button :aria-pressed="loopPlayback" :disabled="recorder.isRecording.value" @click="loopPlayback=!loopPlayback" title="循环播放整个工程；录制只播放一次">循环播放{{ loopPlayback ? '：开' : '：关' }}</button><span>{{ formatTimecode(time,project.fps) }} / {{ formatTimecode(project.duration,project.fps) }}</span><label>定位 <TimecodeInput label="播放头时间" :value="time" :fps="project.fps" :max="project.duration" :disabled="locked" @change="seek" /></label><label>总时长 <TimecodeInput label="工程总时长" :value="project.duration" :fps="project.fps" :min="0.5" :max="600" :disabled="locked" @begin-edit="beginEdit" @end-edit="endEdit" @change="changeDuration" /></label><label>FPS <select :value="project.fps" :disabled="locked" @change="changeFps($event.target.value)"><option v-for="n in [24,30,60]" :key="n">{{n}}</option></select></label><label>背景 <input type="color" :value="project.background" @focus="beginEdit" @blur="endEdit" @input="changeBackground($event.target.value)" :disabled="locked" /></label><button v-if="recorder.canRecord.value" :disabled="loading || (!recorder.isRecording.value && !project.clips.length)" @click="record">{{ recorder.isRecording.value ? '结束录制' : '录制场景' }}</button><span v-if="loading" class="loading-label">模型加载中…</span></div>
