        <MultiTimeline v-show="!previewExpanded" :clips="project.clips" :duration="project.duration" :fps="project.fps" :time="time" :selected="selected" :selectedId="selectedId" :labels="paramLabels" :pose="selectedPose" :runtimes="runtimes" :transform-fields="transformFields" :disabled="locked" :navigation-disabled="loading || recorder.isRecording.value" @select="selectedId=$event" @seek="seek" @batch-clips="batchClips" @layer-state="changeLayerState" @rename-layer="renameLayer" @reorder-layer="reorderLayer" @edit-clip="editClip" @begin-edit="beginEdit" @end-edit="endEdit" @remove-key="removeKey" @batch-keys="batchKeys" @move-key="moveKey" @edit-key-value="editKeyValue" @toggle-key="toggleTimelineKey" @edit-event="editEvent" @paste-event="pasteEvent" @remove-event="removeEvent" @delete-selected="deleteSelected" />
      </main>
      <aside v-show="!previewExpanded && showInspector" class="inspector"><h3>片段属性</h3><template v-if="selected"><p v-if="selected.layerLocked">图层已锁定，请在时间线左侧解锁。</p><fieldset :disabled="editLocked" class="inspector-fields">
        <input aria-label="片段名称" :value="selected.name" @focus="beginEdit" @blur="endEdit" @input="renameClip($event.target.value)" :disabled="locked" />
