        <div v-for="p in visibleParams" :key="p.key" class="scene-param" :data-param-id="p.key"><span :title="p.key">{{p.label}}{{ numericDisplay(p.key,p).unit }}</span><div><input :aria-label="p.label" type="number" :min="numericDisplay(p.key,p).min" :max="numericDisplay(p.key,p).max" step="1" :value="numericDisplay(p.key,p).toDisplay(selectedPose.params[p.key] ?? p.default)" :disabled="locked" @focus="beginEdit" @blur="$event.target.value=numericDisplay(p.key,p).toDisplay(selectedPose.params[p.key] ?? p.default);endEdit()" @input="editParam(p,numericDisplay(p.key,p).toNative($event.target.value))" /><button :class="{keyed:hasKey(p.key)}" :disabled="locked" @click="toggleKey(p.key,selectedPose.params[p.key] ?? p.default)" title="添加/删除当前帧关键帧">◆</button><button :aria-label="'重置'+p.label" :disabled="locked" @click="resetParam(p)">重置</button></div><input :aria-label="p.label+'滑条'" type="range" @pointerdown="beginEdit" @pointerup="endEdit" @pointercancel="endEdit" :min="numericDisplay(p.key,p).min" :max="numericDisplay(p.key,p).max" step="1" :value="numericDisplay(p.key,p).toDisplay(selectedPose.params[p.key] ?? p.default)" :disabled="locked" @focus="beginEdit" @blur="$event.target.value=numericDisplay(p.key,p).toDisplay(selectedPose.params[p.key] ?? p.default);endEdit()" @input="editParam(p,numericDisplay(p.key,p).toNative($event.target.value))" /></div></template>
      </fieldset></template><p v-else>在画布或时间线上选择模型片段，编辑其显示时长、动作和参数。</p></aside>
    </div>
  </div>
</template>
<script setup>
import { ref } from 'vue'
import { numericDisplay } from './numericDisplay.js'
import TimecodeInput from './components/TimecodeInput.vue'
import { formatTimecode } from './timecode.js'
import ShortcutManual from './components/ShortcutManual.vue'
import SceneCanvas from './components/SceneCanvas.vue'
import MultiTimeline from './components/MultiTimeline.vue'
import { clipVisible } from './sceneProject.js'
import { useSceneEditor } from './composables/useSceneEditor.js'
const emit=defineEmits(['legacy'])
const previewExpanded=ref(false),showAssets=ref(window.innerWidth>=1100),showInspector=ref(window.innerWidth>=800)
const {batchClips,editLocked,changeLayerState,project,runtimes,selectedId,playing,loopPlayback,message,assetSearch,paramSearch,allParams,autoTransform,sceneCanvas,projectInput,recorder,locked,time,selected,runtime,loading,canSplit,selectedPose,paramLabels,filteredModels,visibleParams,transformFields,hasKey,previewMotionName,previewExpressionName,activePreview,previewMotionInfo,previewProgress,preview,resetPreview,endPreview,mouseMoved,changeMouseTrack,addChosenEvent,canUndo,canRedo,undo,redo,beginEdit,endEdit,renameClip,changeBackground,backgroundInput,backgroundLoading,uploadingBackground,uploadBackground,removeBackgroundImage,resetBackground,addModel,renameLayer,reorderLayer,editClip,editTiming,editTransform,resetPlacement,moveModel,transformModel,editParam,resetParam,toggleKey,removeKey,moveKey,batchKeys,editKeyValue,editEvent,pasteEvent,removeEvent,duplicate,split,deleteSelected,runtimeReady,disposeRuntime,runtimeError,addEvent,play,pause,seek,changeDuration,changeFps,record,exportProject,importProject}=useSceneEditor()
function toggleTimelineKey(key) {
  const p=runtime.value?.groups.flatMap(g=>g.params).find(p=>p.key===key)
  toggleKey(key,key.startsWith('@') ? selectedPose.value.transform[key.slice(1)] : selectedPose.value.params[key] ?? p?.default ?? 0)
